-- =====================================================================
-- ALIMENTOS GENÉRICOS VERIFICADOS — BEDCA (21 de octubre de 2026)
-- =====================================================================
-- Fuente: Base de Datos Española de Composición de Alimentos (BEDCA),
-- Agencia Española de Seguridad Alimentaria y Nutrición. Valores por 100 g
-- de porción comestible. Energía convertida de kJ a kcal (/4,184); sal a
-- partir del sodio (x2,5).
--
-- Nueve filas de BEDCA con valores imposibles (cocidos que traen los
-- valores del crudo, conservas con la energía mal) se han dejado FUERA, y
-- los cocidos más usados (arroz, pasta, legumbres) y tres carnes magras
-- entran con valores del USDA FoodData Central (SR Legacy, dominio
-- público), marcados con source = 'usda'.
--
-- Requiere NUTRICION_2026-10-21.sql (columnas is_generic, source).
-- Idempotente: se puede volver a ejecutar y actualiza los valores.
-- 954 alimentos.
-- =====================================================================

ON CONFLICT (code) DO UPDATE SET
    product_name = EXCLUDED.product_name,
    "energy-kcal_100g" = EXCLUDED."energy-kcal_100g",
    proteins_100g = EXCLUDED.proteins_100g,
    fat_100g = EXCLUDED.fat_100g,
    carbohydrates_100g = EXCLUDED.carbohydrates_100g,
    sugars_100g = EXCLUDED.sugars_100g,
    fiber_100g = EXCLUDED.fiber_100g,
    salt_100g = EXCLUDED.salt_100g,
    "saturated-fat_100g" = EXCLUDED."saturated-fat_100g",
    is_generic = true,
    source = EXCLUDED.source;

